// Vector001: fixed-point 3D vector arithmetic: sums, cross products and dot products of random vectors.
// Generated by `dotnet run --project Runner -c Release -- generate`; change the generator, not this file.
package group0

import "baseline/common"

type vector001Vec3 struct {
	x, y, z uint64
}

func (v vector001Vec3) add(other vector001Vec3) vector001Vec3 {
	return vector001Vec3{v.x + other.x, v.y + other.y, v.z + other.z}
}

func (v vector001Vec3) scale(factor uint64) vector001Vec3 {
	return vector001Vec3{v.x * factor, v.y * factor, v.z * factor}
}

func (v vector001Vec3) dot(other vector001Vec3) uint64 {
	return v.x*other.x + v.y*other.y + v.z*other.z
}

func (v vector001Vec3) cross(other vector001Vec3) vector001Vec3 {
	return vector001Vec3{
		v.y*other.z - v.z*other.y,
		v.z*other.x - v.x*other.z,
		v.x*other.y - v.y*other.x,
	}
}

func vector001Simulate(seed uint64) uint64 {
	rng := common.NewRng(seed)
	var sum vector001Vec3
	for range 22 {
		x := rng.Next()
		y := rng.Next()
		z := rng.Next()
		v := vector001Vec3{x, y, z}
		w := v.cross(sum).add(v.scale(0x46FC33FF15BEF56B))
		sum = sum.add(w)
		if sum.dot(v)&1 == 1 {
			sum = sum.scale(0xDD4AAB4072C7E9)
		}
	}
	return sum.dot(sum) ^ sum.x
}

func vector001KernelA(x, y uint64) uint64 {
	a := x & (y << 6)
	b := y >> 47
	for i := uint64(0); i < 6; i++ {
		a = (a + i) * (i ^ b)
		b = b * common.Rotl(i << 49, 12)
		if ((a - 156) & 1023) != 523 {
			a = a | ((b | 0x3376D34B666D4591) % 728)
		} else {
			b = (b * a) + (b ^ 154)
		}
	}
	if ((b * x) & 1023) == 529 {
		a = a & ((b - 88) >> 26)
	} else {
		b = b | (a + x)
	}
	c := x + (b * 55)
	return c ^ (a + b)
}

func vector001KernelB(x, y uint64) uint64 {
	a := common.Rotl(x, 27)
	b := y & 255
	for i := uint64(0); i < 6; i++ {
		a = a - ((b + x) + (b & 118))
		b = common.Rotl(b, 18) - (b << 21)
		if ((i ^ b) & 65535) > 34281 {
			a = a - ((i >> 55) + 0xA01421F728036A41)
		} else {
			b = common.Rotl(b * 158, 12)
		}
	}
	c := common.Rotl(a, 16) << 8
	d := (b << 1) & (a ^ 40)
	return (c ^ (a ^ b)) + d
}

// Vector001Mix mixes x through this module's kernels.
func Vector001Mix(x uint64) uint64 {
	return vector001KernelB(vector001KernelA(x, 0x339596C5AC4F1FB1), x ^ 0x3A486CEBCEFA48B7)
}

// Vector001Run runs this module from seed and mixes in the modules it depends on.
func Vector001Run(seed uint64) uint64 {
	r := vector001Simulate(seed ^ 0xD0F1527C73B2EFBD)
	return Vector001Mix(r)
}
